package com.gomgomapps.math.core;
import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class FractionReductionSupplyTest {
 @Test public void properImproperZeroAndAlreadyLowestKeepOriginalParts(){for(int[]v:new int[][]{{18,30},{36,24},{0,30},{7,11},{108,108},{120,1}}){Question q=FractionReductionSupply.make(v[0],v[1]);HelpPlan h=HelpPlan.forQuestion(q);assertEquals(5,h.size());assertFalse(h.canTransfer());assertEquals(""+v[0],q.studyGuide.frames.get(0).expected);assertEquals(""+v[1],q.studyGuide.frames.get(1).expected);Checker c=new Checker();assertTrue(c.check(q,List.of(),List.of(Rational.of(v[0],v[1]).toString())).correct());assertFalse(c.check(q,List.of(),List.of(""+(v[0]+1)+"/"+v[1])).correct());if(v[0]==18)assertEquals(Checker.Status.INPUT_NEEDED,c.check(q,List.of(),List.of("9/15")).status);assertTrue(h.restore(null,q.id).entries.stream().allMatch(String::isEmpty));}}
 @Test public void finiteDomainCompletesBeforeOldest(){CurriculumLimits l=new CurriculumLimits("variedFacts=true;maxGiven=3;maxResult=3;nonnegative=true");Random r=new Random(272);Map<String,Integer>recent=new LinkedHashMap<>();for(int i=0;i<12;i++){Question q=FractionReductionSupply.next(r,l,recent);assertFalse(recent.containsKey(q.signature()));recent.put(q.signature(),i);}assertEquals(recent.keySet().iterator().next(),FractionReductionSupply.next(r,l,recent).signature());assertFalse(FractionReductionSupply.selected("reduce",CurriculumLimits.NONE));}
 @Test public void ordinaryNA6FreshSupplyUsesExistingFractionForm(){String pack="na-nied-primary-2024-v1";CurriculumLimits l=GlobalCurriculum.limits(pack,"reduce",6);assertTrue(FractionReductionSupply.selected("reduce",l));Generator g=new Generator(new Random(272));List<String>recent=new ArrayList<>();boolean proper=false,improper=false;int reducible=0;for(int i=0;i<100;i++){Question q=g.next("reduce",recent,false,l);assertFalse(recent.contains(q.signature()));recent.add(q.signature());assertTrue(FractionInput.defaultFraction(q));assertEquals(5,HelpPlan.forQuestion(q).size());int n=Integer.parseInt(q.studyGuide.frames.get(0).expected),d=Integer.parseInt(q.studyGuide.frames.get(1).expected);reducible+=Integer.parseInt(q.studyGuide.frames.get(2).expected)>1&&n>0?1:0;proper|=n>0&&n<d;improper|=n>d;assertTrue(n<=120&&d<=120);}assertTrue(proper&&improper);assertTrue(reducible>=70);assertFalse(FractionReductionSupply.selected("reduce",GlobalCurriculum.limits("england-primary-2021-v1","reduce",6)));}
}
